"""Execute production surface against minimal graphics stubs; no Android/device claim."""
from pathlib import Path
import subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
stubs={
'android/content/Context.java':'package android.content; public class Context { public android.content.res.Resources getResources(){return new android.content.res.Resources();}}',
'android/content/res/Resources.java':'package android.content.res; public class Resources {public static class NotFoundException extends RuntimeException{} public Metrics getDisplayMetrics(){return new Metrics();} public static class Metrics{public float density=2;}}',
'android/graphics/Bitmap.java':'package android.graphics; public class Bitmap{}',
'android/graphics/BitmapFactory.java':'package android.graphics; public class BitmapFactory {public static int calls;public static boolean oom,good;public static class Options{public int inSampleSize;public boolean inScaled;}public static Bitmap decodeResource(android.content.res.Resources r,int id,Options o){calls++;if(oom)throw new OutOfMemoryError("synthetic optional allocation");return good?new Bitmap():null;}}',
'android/graphics/Shader.java':'package android.graphics;public class Shader{public enum TileMode{MIRROR}}',
'android/graphics/BitmapShader.java':'package android.graphics;public class BitmapShader extends Shader{public void setLocalMatrix(Matrix m){}public BitmapShader(Bitmap b,TileMode x,TileMode y){if(b==null)throw new AssertionError("null shader");}}',
'android/graphics/Matrix.java':'package android.graphics; public class Matrix {public void setScale(float x,float y){if(x!=2||y!=2)throw new AssertionError("density");}}',
'android/graphics/ColorMatrixColorFilter.java':'package android.graphics;public class ColorMatrixColorFilter extends ColorFilter{public ColorMatrixColorFilter(float[] values){if(values.length!=20)throw new AssertionError("matrix");}}',
'android/graphics/ColorFilter.java':'package android.graphics;public class ColorFilter{}',
'android/graphics/PorterDuff.java':'package android.graphics;public class PorterDuff{public enum Mode{MULTIPLY}}',
'android/graphics/PorterDuffColorFilter.java':'package android.graphics;public class PorterDuffColorFilter extends ColorFilter{public static int allocations;public PorterDuffColorFilter(int c,PorterDuff.Mode m){allocations++;}}',
'android/graphics/Paint.java':'package android.graphics;public class Paint{public static final int ANTI_ALIAS_FLAG=1;public int color;public Shader shader;public int alpha;public enum Style{STROKE,FILL}public Paint(int f){}public void setShader(Shader s){shader=s;}public void setColor(int c){color=c;}public void setColorFilter(ColorFilter f){}public void setAlpha(int a){alpha=a;}public void setStrokeWidth(float w){}public void setStyle(Style s){}}',
'android/graphics/Rect.java':'package android.graphics;public class Rect{public int left=30,top=40,right=230,bottom=340;}',
'android/graphics/RectF.java':'package android.graphics;public class RectF{public float left,top,right,bottom;public void set(Rect r){left=r.left;top=r.top;right=r.right;bottom=r.bottom;}public void inset(float x,float y){left+=x;top+=y;right-=x;bottom-=y;}}',
'android/graphics/Path.java':'package android.graphics;public class Path{public enum Direction{CW}public void reset(){}public void addRoundRect(RectF r,float x,float y,Direction d){}}',
'android/graphics/Outline.java':'package android.graphics;public class Outline{public void setRoundRect(Rect b,float radius){if(radius!=30)throw new AssertionError("control outline");}public void setAlpha(float alpha){if(alpha!=1f)throw new AssertionError("outline alpha");}}',
'android/graphics/PixelFormat.java':'package android.graphics;public class PixelFormat{public static final int TRANSLUCENT=-3;}',
'android/graphics/Canvas.java':'''package android.graphics;public class Canvas{public int cream,teal,stitches,lips,highlights,grain;public void save(){}public void restore(){}public void clipPath(Path p){}public void drawRect(RectF r,Paint p){drawRect(r.left,r.top,r.right,r.bottom,p);}public void drawRect(float l,float t,float r,float b,Paint p){if(l<30||t<40||r>230||b>340)throw new AssertionError("bounds");if(p.color==0x38715C3E||p.color==0x4017233D)lips++;if(p.color==0xB3FFFFFF)highlights++;if(p.shader!=null&&p.alpha==72)grain++;if(p.color==0xFFF5EFE0&&p.shader==null)cream++;if(p.color==0xFF176079)teal++;}public void drawLine(float x,float y,float xx,float yy,Paint p){if(x<30||yy>340)throw new AssertionError("stitch bounds");stitches++;}public void drawRoundRect(RectF r,float x,float y,Paint p){if(r.left<31||r.top<41||r.right>229||r.bottom>339)throw new AssertionError("stroke inset");}}''',
'android/graphics/drawable/Drawable.java':'package android.graphics.drawable;public abstract class Drawable{public android.graphics.Rect getBounds(){return new android.graphics.Rect();}public void getOutline(android.graphics.Outline o){}public abstract void draw(android.graphics.Canvas c);public abstract void setAlpha(int a);public abstract void setColorFilter(android.graphics.ColorFilter f);public abstract int getOpacity();}',
'ai/codeandcraft/secondbrain/PopUi.java':'package ai.codeandcraft.secondbrain;public class PopUi{public static final int PAPER=0xFFF5EFE0,LINE=0xFFC9BFA8;}',
'ai/codeandcraft/secondbrain/R.java':'package ai.codeandcraft.secondbrain;public class R{public static class drawable{public static final int woven_texture=1,paper_grain=2;}}',
'ai/codeandcraft/secondbrain/Probe.java':'''package ai.codeandcraft.secondbrain;import android.graphics.*;import android.graphics.drawable.Drawable;public class Probe{public static void main(String[] args){BitmapFactory.oom=args.length>0&&args[0].equals("oom");BitmapFactory.good=args.length>0&&args[0].equals("good");android.content.Context c=new android.content.Context();Drawable page=NotebookSurface.page(c),card=NotebookSurface.card(c,0xFFF5EFE0,0);int filters=PorterDuffColorFilter.allocations;Canvas canvas=new Canvas();for(int i=0;i<20;i++){page.draw(canvas);card.draw(canvas);}NotebookSurface.cloth(c);if(BitmapFactory.calls!=2)throw new AssertionError("decode retry");if(PorterDuffColorFilter.allocations!=filters+1)throw new AssertionError("draw tint allocation");if(canvas.cream!=40||canvas.teal!=40||canvas.stitches==0)throw new AssertionError("flat fallback");if(BitmapFactory.good&&canvas.grain!=40)throw new AssertionError("visible grain overlay");Drawable control=NotebookSurface.control(c,0xFF244ACB,0xFF193698);control.draw(canvas);control.getOutline(new Outline());if(canvas.lips!=21||canvas.highlights!=21)throw new AssertionError("contained edges");System.out.println("PASS: synthetic "+(BitmapFactory.oom?"OOM":BitmapFactory.good?"success":"null")+" decode: cached attempts, flat cream/teal/stitches, cached draw tint and bounded stroke");}}'''
}
with tempfile.TemporaryDirectory(prefix='.fallback-host-',dir=ROOT/'tests/woven-ui') as tmp:
    work=Path(tmp)
    for name,body in stubs.items():
        p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body)
    production=ROOT/'app/src/main/java/ai/codeandcraft/secondbrain/NotebookSurface.java'
    subprocess.run(['javac','-d',str(work),*[str(work/p) for p in stubs],str(production)],check=True)
    for mode in [[],['oom'],['good']]:subprocess.run(['java','-cp',str(work),'ai.codeandcraft.secondbrain.Probe',*mode],check=True)
